SELECT MIN(a.id) AS id, a.productie_id, p.titel AS productie, a.plandag, COUNT(*) AS activiteiten, SUM(a.soort = 'voorstelling') AS voorstellingen, SUM(a.soort = 'repetitie') AS repetities, SUM(a.soort = 'opbouw') AS opbouw, SUM(a.soort = 'afbouw') AS afbouw, SUM(a.soort = 'reis') AS reis, SUM(a.soort = 'overnachting') AS overnachting, SUM(a.soort = 'maaltijd') AS maaltijd, SUM(a.soort = 'vergadering') AS vergadering, SUM(a.soort = 'andere') AS andere FROM activiteit a JOIN productie p ON p.id = a.productie_id WHERE a.deleted_at IS NULL GROUP BY a.productie_id, a.plandag
